const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),map=document.getElementById('minimap'),mx=map.getContext('2d');
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),pick=a=>a[Math.floor(Math.random()*a.length)];
let W=innerWidth,H=innerHeight,DPR=1,now=0,last=0,active=false,vehicle=false,flying=false,toastTimer=0;
const player={x:0,z:0,vx:0,vz:0,heading:0,walk:0};let cash=8450,rep=12,wanted=0,job=false;
const keys={},buildings=[],cars=[],rain=[];
const districts=['Glassline','Old Marina','Juniper Heights','Market Row','Southpoint'];
const missionList=[['A Favor After Dark','The Blue Hour needs a discreet delivery across the canal. No questions, good tip.','+$ 1,200 · +8 REP'],['A Room With a View','A rooftop suite is coming up. Get there before the city wakes.','−$ 2,800 · +12 REP'],['The Long Way Home','Someone left a vintage coupe outside the Meridian. Bring it back in one piece.','+$ 950 · +6 REP'],['One Good Connection','The people at the Solace want a familiar face at the door tonight.','+$ 600 · +10 REP']];let missionIndex=0;
const palettes=[['#213c3a','#38605a','#99b29b'],['#292f3e','#515b68','#c1a982'],['#2d413d','#4d6859','#adc183'],['#473936','#79604b','#dbac68'],['#27383f','#48646c','#8ec6c2']];
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);seedWorld()}window.addEventListener('resize',resize);
function seedWorld(){buildings.length=0;for(let side of [-1,1])for(let i=0;i<34;i++){let depth=(i/34)*1.5+.08,lat=side*(1.15+rand(0,2.4));buildings.push({side,depth,lat,w:rand(.16,.42),h:rand(.15,.64),pal:pick(palettes),seed:Math.random(),type:Math.random()});}cars.length=0;for(let i=0;i<11;i++)cars.push({z:rand(-1,1),lane:pick([-1,1]),color:pick(['#b9cbb8','#e5bc70','#71b9b1','#c77360','#71899b']),speed:rand(.07,.17)});rain.length=0;for(let i=0;i<170;i++)rain.push({x:Math.random()*W,y:Math.random()*H,len:rand(7,22),v:rand(300,700)});}
function project(lat,depth){let d=Math.max(.02,depth),scale=.22+d*.82;return{x:W/2+(lat-player.x*.48)*W*.24*scale,y:H*.39+d*H*.46-player.z*H*.17*scale,scale};}
function poly(points,fill,stroke){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.stroke();}}
function drawSky(){let g=ctx.createLinearGradient(0,0,0,H*.7);g.addColorStop(0,'#101e20');g.addColorStop(.42,'#29413e');g.addColorStop(1,'#68796e');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);let glow=ctx.createRadialGradient(W*.53,H*.36,4,W*.53,H*.36,W*.54);glow.addColorStop(0,'#e1bd8750');glow.addColorStop(1,'#d7c08a00');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H*.75);ctx.fillStyle='#e5cb9a';ctx.globalAlpha=.72;ctx.beginPath();ctx.arc(W*.72,H*.24,Math.min(W,H)*.042,0,7);ctx.fill();ctx.globalAlpha=1;
 // distant skyline layers
 for(let layer=0;layer<3;layer++){let base=H*(.49+layer*.045),x=0;while(x<W){let bw=rand(18,65)*(W/1100),bh=rand(.04,.18)*H*(layer===0?.8:1),col=['#263c3a','#203432','#182b2a'][layer];ctx.fillStyle=col;ctx.fillRect(x,base-bh,bw,bh+H*.08);if(layer>0){ctx.fillStyle='#e3bd7a';for(let wy=base-bh+8;wy<base;wy+=11)for(let wx=x+4;wx<x+bw-4;wx+=9)if(Math.random()>.43){ctx.globalAlpha=.25+Math.random()*.55;ctx.fillRect(wx,wy,2,4)}ctx.globalAlpha=1}x+=bw+2;}}
}
function drawStreet(){let horizon=H*.49,shift=player.x*W*.09; // pavement and street depth
 poly([{x:W*.42-shift*.2,y:horizon},{x:W*.59-shift*.2,y:horizon},{x:W*1.12,y:H},{x:-W*.12,y:H}],'#1a2524');
 // sidewalk
 poly([{x:0,y:horizon},{x:W*.42-shift*.2,y:horizon},{x:-W*.12,y:H},{x:0,y:H}],'#3b4540');poly([{x:W*.59-shift*.2,y:horizon},{x:W,y:horizon},{x:W,y:H},{x:W*1.12,y:H}],'#414a43');
 // road reflections
 for(let i=0;i<40;i++){let y=horizon+((i*73+player.z*163)% (H*.55)),t=(y-horizon)/(H*.51),x=rand(W*.18,W*.82),len=rand(8,95)*t;ctx.globalAlpha=rand(.025,.12);ctx.strokeStyle=pick(['#d0bc93','#88c0b0','#d3e2d4']);ctx.lineWidth=rand(1,4)*t+.3;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+len,y-rand(0,3));ctx.stroke()}ctx.globalAlpha=1;
 // lane markers perspective
 for(let i=0;i<16;i++){let d=((i/16+player.z*.17)%1+1)%1, y=horizon+d*(H*.52), width=2+d*5;ctx.fillStyle='#d5cba766';ctx.fillRect(W*.5-width/2,y,width,4+d*12)}
 // curb lines
 ctx.strokeStyle='#c2b79a44';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(W*.42-shift*.2,horizon);ctx.lineTo(-W*.12,H);ctx.moveTo(W*.59-shift*.2,horizon);ctx.lineTo(W*1.12,H);ctx.stroke();}
function drawBuildings(){for(const b of buildings){let depth=((b.depth-player.z*.2+.2)%1.6)+.02,p=project(b.lat,depth),w=b.w*W*p.scale,h=b.h*H*p.scale;if(p.x+w<0||p.x-w>W)continue;let x=p.x+(b.side<0?w*.45:-w*.45),base=p.y;let top=base-h;let [dark,face,lit]=b.pal;let sideW=w*.22;poly([{x:x-w/2,y:base},{x:x-w/2,y:top+h*.08},{x:x+w/2-sideW,y:top},{x:x+w/2-sideW,y:base}],face);poly([{x:x+w/2-sideW,y:top},{x:x+w/2,y:top+h*.08},{x:x+w/2,y:base},{x:x+w/2-sideW,y:base}],dark);poly([{x:x-w/2,y:top+h*.08},{x:x+w/2-sideW,y:top},{x:x+w/2,y:top+h*.08},{x:x-w/2,y:top+h*.16}],lit+'55');
 // lit windows grid
 let rows=Math.min(13,Math.floor(h/(10*p.scale+4))),cols=Math.min(8,Math.floor(w/(12*p.scale+5)));for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){let xx=x-w/2+6*p.scale+c*(w-12*p.scale)/Math.max(1,cols),yy=top+12*p.scale+r*(h-17*p.scale)/Math.max(1,rows);if(Math.sin((r+1)*91+(c+1)*33+b.seed*200)>-.25){ctx.globalAlpha=.25+Math.abs(Math.sin(c*12+r*5+b.seed*8))*.5;ctx.fillStyle=pick([lit,'#f3d09a','#8fc7bd']);ctx.fillRect(xx,yy,Math.max(1,3*p.scale),Math.max(1,5*p.scale));}}ctx.globalAlpha=1;
 // awning / neon edge
 if(b.type>.78&&depth>.5){ctx.globalAlpha=.65;ctx.fillStyle=b.seed>.5?'#b66f55':'#5ccabd';ctx.fillRect(x-w*.4,base-h*.19,w*.8,Math.max(2,3*p.scale));ctx.globalAlpha=1;}
 }}
function drawProps(){for(let i=0;i<8;i++){let d=((i/8+player.z*.24)%1+1)%1,p=project(-.8,d),h=(15+20*d)*DPR/DPR,x=p.x-26*p.scale,y=p.y;ctx.fillStyle='#202e2a';ctx.fillRect(x,y-h,3*p.scale,h);ctx.fillStyle='#cfb379';ctx.globalAlpha=.35;ctx.beginPath();ctx.ellipse(x,y,10*p.scale,4*p.scale,0,0,7);ctx.fill();ctx.globalAlpha=1;} // streetlamps
 for(let s of [-1,1])for(let i=0;i<3;i++){let d=((i/3+player.z*.2)%1+1)%1,p=project(s*1.1,d),h=H*.12*p.scale,x=p.x,y=p.y;ctx.strokeStyle='#192623';ctx.lineWidth=2*p.scale;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x,y-h);ctx.lineTo(x+s*10*p.scale,y-h);ctx.stroke();ctx.fillStyle='#f6d5a0';ctx.shadowColor='#f6d5a0';ctx.shadowBlur=15*p.scale;ctx.beginPath();ctx.arc(x+s*10*p.scale,y-h,2*p.scale,0,7);ctx.fill();ctx.shadowBlur=0;}}
function drawCars(dt){for(let c of cars){c.z+=c.speed*dt*(player.vz>=0?1:-1);if(c.z>1.3)c.z=-.2;if(c.z<-.3)c.z=1.2;let d=c.z,p=project(c.lane*.28,d),size=10+p.scale*20,y=p.y;if(y<H*.5||y>H+20)continue;ctx.fillStyle='#070d0c77';ctx.beginPath();ctx.ellipse(p.x,y,size*1.15,size*.27,0,0,7);ctx.fill();ctx.fillStyle=c.color;ctx.beginPath();ctx.moveTo(p.x-size,y-size*.25);ctx.lineTo(p.x-size*.68,y-size*.75);ctx.lineTo(p.x+size*.58,y-size*.75);ctx.lineTo(p.x+size,y-size*.2);ctx.lineTo(p.x+size,y+size*.18);ctx.lineTo(p.x-size,y+size*.18);ctx.fill();ctx.fillStyle='#86aaa2';ctx.fillRect(p.x-size*.55,y-size*.67,size*1.05,size*.23);ctx.fillStyle='#ffe0a6';ctx.fillRect(p.x-size*.9,y-size*.05,size*.17,size*.09);ctx.fillRect(p.x+size*.74,y-size*.05,size*.17,size*.09);}}
function drawPlayer(){let x=W*.5-player.x*W*.055,y=H*.79-(player.z%1)*H*.012;if(flying){y-=30+Math.sin(now*5)*9}if(vehicle){ctx.fillStyle='#060b0a88';ctx.beginPath();ctx.ellipse(x,y+6,30,9,0,0,7);ctx.fill();ctx.fillStyle='#566b61';ctx.beginPath();ctx.moveTo(x-40,y);ctx.lineTo(x-31,y-15);ctx.lineTo(x-18,y-23);ctx.lineTo(x+22,y-23);ctx.lineTo(x+39,y-10);ctx.lineTo(x+42,y+1);ctx.closePath();ctx.fill();ctx.fillStyle='#8fa89a';ctx.beginPath();ctx.moveTo(x-17,y-20);ctx.lineTo(x-10,y-31);ctx.lineTo(x+14,y-31);ctx.lineTo(x+25,y-18);ctx.fill();ctx.fillStyle='#ff7462';ctx.fillRect(x-37,y-5,5,4);ctx.fillRect(x+32,y-5,5,4);return}
 ctx.fillStyle='#07100d88';ctx.beginPath();ctx.ellipse(x,y+5,13,5,0,0,7);ctx.fill();let bob=Math.sin(player.walk)*2;ctx.strokeStyle='#172321';ctx.lineWidth=6;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(x-3,y-3);ctx.lineTo(x-5+(Math.sin(player.walk)*4),y+9);ctx.moveTo(x+3,y-3);ctx.lineTo(x+6-Math.sin(player.walk)*4,y+9);ctx.stroke();ctx.fillStyle='#d8d1bd';ctx.beginPath();ctx.ellipse(x,y-13+bob,7,10,-.1,0,7);ctx.fill();ctx.fillStyle='#dab18a';ctx.beginPath();ctx.arc(x,y-28+bob,6,0,7);ctx.fill();ctx.fillStyle='#253832';ctx.beginPath();ctx.arc(x,y-30+bob,6.2,Math.PI,0);ctx.fill();}
function drawRain(dt){ctx.strokeStyle='#bedad148';ctx.lineWidth=.8;ctx.beginPath();for(let r of rain){r.y+=r.v*dt;r.x-=r.v*.08*dt;if(r.y>H+20){r.y=-20;r.x=Math.random()*W}ctx.moveTo(r.x,r.y);ctx.lineTo(r.x-4,r.y+r.len)}ctx.stroke()}
function drawMinimap(){let w=map.width,h=map.height;mx.clearRect(0,0,w,h);mx.fillStyle='#10201c';mx.fillRect(0,0,w,h);for(let i=0;i<8;i++){mx.fillStyle=i%2?'#20322c':'#263a32';mx.fillRect((i%4)*87,Math.floor(i/4)*118,70,95)}mx.strokeStyle='#54645a';mx.lineWidth=12;mx.beginPath();mx.moveTo(0,118);mx.lineTo(w,118);mx.moveTo(154,0);mx.lineTo(154,h);mx.stroke();mx.strokeStyle='#d9ca9760';mx.lineWidth=1;mx.setLineDash([6,7]);mx.beginPath();mx.moveTo(0,118);mx.lineTo(w,118);mx.moveTo(154,0);mx.lineTo(154,h);mx.stroke();mx.setLineDash([]);for(let i=0;i<7;i++){let x=(i*57+30)%w,y=(i*39+22)%h;mx.fillStyle=i===3?'#d8ff64':'#e9bd7a';mx.globalAlpha=.4+Math.sin(now*2+i)*.3;mx.beginPath();mx.arc(x,y,2.4,0,7);mx.fill()}mx.globalAlpha=1;mx.fillStyle='#fff';mx.beginPath();mx.arc(154,118,5,0,7);mx.fill();mx.strokeStyle='#d8ff64';mx.lineWidth=2;mx.stroke();}
function update(dt){let up=keys.w||keys.ArrowUp,down=keys.s||keys.ArrowDown,left=keys.a||keys.ArrowLeft,right=keys.d||keys.ArrowRight;let accel=keys.Shift?1.8:1;let speed=vehicle?1.6:flying?1.25:0.72;player.vx+=(Number(right)-Number(left))*speed*accel*dt*2;player.vz+=(Number(up)-Number(down))*speed*accel*dt*2;player.vx*=Math.pow(.08,dt);player.vz*=Math.pow(.08,dt);player.x=clamp(player.x+player.vx*dt,-3,3);player.z=clamp(player.z+player.vz*dt,-1.8,1.8);if(Math.abs(player.vx)+Math.abs(player.vz)>.02)player.walk+=dt*10;}
function frame(ts){let dt=Math.min(.04,(ts-last)/1000||0);last=ts;now=ts/1000;update(dt);drawSky();drawStreet();drawBuildings();drawProps();drawCars(dt);drawPlayer();drawRain(dt);drawMinimap();requestAnimationFrame(frame)}

function say(text){let t=document.getElementById('toast');t.textContent=text;t.style.opacity=1;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.opacity=.62,4500)}function feed(text){let el=document.createElement('div');el.className='feed-item';el.innerHTML=text;document.getElementById('feed').prepend(el);setTimeout(()=>el.remove(),5100)}function updateDistrict(){let id=Math.floor((Math.sin(player.x*.5+player.z*.3)+1)*2.49);document.getElementById('district').textContent=districts[clamp(id,0,4)];document.getElementById('clock').textContent='01:'+String((42+Math.floor(now*2))%60).padStart(2,'0')}
function changeWanted(n){wanted=clamp(wanted+n,0,5);document.querySelectorAll('#heat i').forEach((e,i)=>e.classList.toggle('on',i<wanted));}
function start(){active=true;document.getElementById('start').classList.add('hidden');document.getElementById('mode').classList.add('show');say('Welcome to South Coast. The night is yours.');feed('<b>01:42</b> &nbsp; You stepped into Glassline.');}
document.getElementById('begin').onclick=start;
document.getElementById('accept').onclick=()=>{if(!active){start();}if(job){say('You already have a lead. Go see where it takes you.');return}job=true;document.getElementById('accept').textContent='TRACKING ✓';document.getElementById('accept').style.color='#d8ff64';say('Opportunity accepted. A marker is live on your field map.');feed('<b>NEW LEAD</b> &nbsp; '+document.getElementById('missionTitle').textContent);}
document.querySelectorAll('.action').forEach(btn=>btn.onclick=()=>{let kind=btn.dataset.action;if(!active)start();if(kind==='business'){if(cash<3000){say('You need $3,000 to put down a deposit. Take a job first.');return}cash-=3000;rep+=4;document.getElementById('cash').textContent='$ '+cash.toLocaleString();document.getElementById('rep').innerHTML=rep+' <small>REP</small>';say('A tiny storefront on Market Row is yours. First chapter of something bigger.');feed('<b>NEW VENTURE</b> &nbsp; Glasshouse Coffee');}
if(kind==='property'){if(cash<1800){say('The landlord wants $1,800 up front.');return}cash-=1800;document.getElementById('cash').textContent='$ '+cash.toLocaleString();say('You have keys to a compact loft above the old marina. Make it home.');feed('<b>PROPERTY</b> &nbsp; Old Marina · Loft 4B');}
if(kind==='social'){rep+=2;document.getElementById('rep').innerHTML=rep+' <small>REP</small>';say('You made a good impression at the Solace. A few new numbers in your phone.');feed('<b>CONNECTION</b> &nbsp; The city remembers a face.');}
if(kind==='mayhem'){changeWanted(1);say('A siren sounds somewhere behind you. The night just got complicated.');feed('<b>DISRUPTION</b> &nbsp; Heat is rising. Lay low.');setTimeout(()=>{if(wanted)changeWanted(-1)},18000)} });
window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();keys[k]=true;if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(!active&&k==='enter')start();if(k==='f'&&!e.repeat){flying=!flying;vehicle=false;document.getElementById('mode').textContent=flying?'FLIGHT MODE · FREE ROAM':'ON FOOT · FREE ROAM';say(flying?'You lift above the boulevard. Take in the whole city.':'Back on the street.');}if(k==='e'&&!e.repeat){if(!active){start();return}if(!vehicle){vehicle=true;flying=false;document.getElementById('mode').textContent='IN A CAR · FREE ROAM';document.getElementById('speed').classList.add('show');say('You slide into a parked coupe. The whole coastline is open.');feed('<b>VEHICLE</b> &nbsp; Keys in the ignition.');}else{vehicle=false;document.getElementById('mode').textContent='ON FOOT · FREE ROAM';document.getElementById('speed').classList.remove('show');say('Back on foot. Keep moving.');}}
if(k==='m'&&!e.repeat){missionIndex=(missionIndex+1)%missionList.length;let m=missionList[missionIndex];document.getElementById('missionTitle').textContent=m[0];document.getElementById('missionCopy').textContent=m[1];document.getElementById('reward').textContent=m[2];document.getElementById('accept').textContent='TAKE JOB ↗';job=false;say('New opportunity came through.');}if(k==='enter'&&active&&job){job=false;cash+=1200;rep+=8;document.getElementById('cash').textContent='$ '+cash.toLocaleString();document.getElementById('rep').innerHTML=rep+' <small>REP</small>';document.getElementById('accept').textContent='TAKE JOB ↗';say('Delivery complete. +$1,200 and the right people know your name.');feed('<b>JOB COMPLETE</b> &nbsp; Your reputation is growing.');}}
);window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});
// Simple touch joystick and contextual interaction for handheld devices.
let touchStart=null;canvas.addEventListener('touchstart',e=>{if(e.touches.length){touchStart={x:e.touches[0].clientX,y:e.touches[0].clientY};if(!active)start()}},{passive:true});canvas.addEventListener('touchmove',e=>{if(!touchStart||!e.touches.length)return;let t=e.touches[0],dx=t.clientX-touchStart.x,dy=t.clientY-touchStart.y;keys.a=dx< -18;keys.d=dx>18;keys.w=dy< -18;keys.s=dy>18},{passive:true});canvas.addEventListener('touchend',()=>{touchStart=null;keys.a=keys.d=keys.w=keys.s=false},{passive:true});
let districtTimer=0;function gameplay(){updateDistrict();if(vehicle){let km=Math.round(Math.abs(player.vz)*84+Math.abs(player.vx)*55);document.getElementById('speed').textContent=km+' KM/H'}if(active&&job&&Math.random()<.001){job=false;cash+=1200;rep+=8;document.getElementById('cash').textContent='$ '+cash.toLocaleString();document.getElementById('rep').innerHTML=rep+' <small>REP</small>';say('Delivery complete. +$1,200 · +8 REP');document.getElementById('accept').textContent='TAKE JOB ↗'}setTimeout(gameplay,350)}
resize();requestAnimationFrame(frame);gameplay();
</script></body></html>

